function UIOverseaTowerInsideDialog:Awake()
    KCookie.Set(Constants.UICacheDataKeys.OVERSEA_TOWER_ANIM_CONTROL, "true")
    self.ImgBg2 = self.BgMask.transform:Find("ImgBg")
    self.ImgSymbol2 = self.ImgSymbol.transform.parent:Find("ImgSymbol2")
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnEnter))
    SetButtonAction(self.BtnUnlock, function()
        OverseaTowerUtils.RequestUnlockNextQuest(self._curQuestId, function()
            ---刷新界面ui
            self:FreshUnLockEffectUI()
        end)
    end)
end

function UIOverseaTowerInsideDialog:InitData()
    self._curQuestId = OverseaTowerUtils.GetCurQuestId(self._curTowerType)
    local t = OverseaTowerUtils.GetAllTowerQuest(self._curTowerType)
    self._allQuests = t
    local _t = {}
    local ind = self:GetInd()
    for k, v in pairs(t) do
        --只显示上下第50层，多了不显示出来
        if math.abs(ind - k) <= 50 then
            table.insert(_t, v)
        end
    end
    self._allQuests = _t
end

function UIOverseaTowerInsideDialog:FreshRectMask()
    local firstQuestId = OverseaTowerUtils.GetFirstQuestId(self._curTowerType)
    local maxQuestId = OverseaTowerUtils.GetMaxQuestId(self._curTowerType)
    local x = 200
    local y = 500
    if self._curQuestId < (firstQuestId + 3) then
        ---修改遮罩的羽化值
        x = 0
    elseif self._curQuestId > (maxQuestId - 3) then
        ---修改遮罩的羽化值
        y = 0
    end
    local viewPoint = self.ScrollView.transform:Find("Viewport")
    if viewPoint then
        ---@type Engine.UI.RectMask2DPro
        local rectMask2DPro = KTool.GetComponent(viewPoint.gameObject, typeof(CS.Engine.UI.RectMask2DPro))
        rectMask2DPro.softnessBT = CS.UnityEngine.Vector2Int(x, y)
    end
end

function UIOverseaTowerInsideDialog:FreshUnLockEffectUI()
    CfUtils.SetUISwitchImage(self.ImgSymbol, self._curTowerType)
    CfUtils.SetUISwitchImage(self.ImgSymbol2, self._curTowerType)
    CfUtils.SetUISwitchParticleSystem(self.UIFX_Shine, self._curTowerType)
    CfUtils.SetUISwitchParticleSystem(self.UIFX_Line, self._curTowerType)
    CfUtils.SetUISwitchParticleSystem(self.UIFX_Glow, self._curTowerType)
    ---播放当前选择解锁的节点进行cell动画播放
    local index = -1
    for position, v in pairs(self._allQuests) do
        if checkNumber(self._curQuestId) == checkNumber(v) then
            index = position
            break
        end
    end
    if index > 0 then
        for itemCount = 1, self.ScrollView.ShownItemCount do
            local cellNode = self.ScrollView:GetShownItemByIndex(itemCount - 1)
            if not isNull(cellNode) then
                ---@type UIOverseaTowerInsideNode
                local nodeEnv = CfUtils.GetLuaScr(cellNode, TowerQuestCellPath)
                if nodeEnv then
                    local cellLuaIndex = nodeEnv:GetLuaIndex()
                    if cellLuaIndex == index then
                        CfUtils.StartCoroutineWithBlocker(function()
                            CfUtils.PlayAnimation(nodeEnv.StatusLock, "OverseaTowerInsideDialog_Cell_Unlock")
                            coroutine.yield(CoYield(0.6))
                            CfUtils.SetActive(nodeEnv.StatusLock, false)
                            self:FillMainQuestInfo()
                            CfUtils.PlayAnimation(self.Unlock, "OverseaTowerInsideDialog_Unlock")
                        end)
                        break
                    end
                end
            end
        end
    end
end

function UIOverseaTowerInsideDialog:FillSelf()
    CfUtils.SetUISwitchImage(self.ImgSymbol, self._curTowerType)
    CfUtils.SetUISwitchImage(self.ImgSymbol2, self._curTowerType)
    CfUtils.SetUISwitchParticleSystem(self.UIFX_Shine, self._curTowerType)
    CfUtils.SetUISwitchParticleSystem(self.UIFX_Line, self._curTowerType)
    CfUtils.SetUISwitchParticleSystem(self.UIFX_Glow, self._curTowerType)

    self:FillQuests()
    self:FillMainQuestInfo()
end

function UIOverseaTowerInsideDialog:FillQuests()
    self:FreshRectMask()
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitListView(#self._allQuests, Bind(self, self.OnGetItemByIndex))
        self.ScrollView:UpdateDisplayItemCount("Cell")
    else
        GameUtils.ReloadData(self.ScrollView, #self._allQuests)
    end
end

---OnGetItemByIndex
---@param listView SuperScrollView.LoopListView2
---@param index number
function UIOverseaTowerInsideDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local position = index + 1
    local data = self._allQuests[position]
    if isSet(data, "isEmpty") then
        ---空节点
        local cell = listView:NewListViewItem("Cell2")
        return cell
    else
        local cell = listView:NewListViewItem("Cell")
        ---@type UIOverseaTowerInsideNode
        local scr = CfUtils.GetLuaScr(cell, TowerQuestCellPath)
        if scr then
            scr:SetLuaIndex(position)
            scr:Refresh(data, position, function()
                self:OnSelectQuest(data)
            end, listView.DisplayItemNumber, listView.DisplayItemCount)
            if listView.DisplayItemNumber < listView.DisplayItemCount then
                listView.DisplayItemNumber = listView.DisplayItemNumber + 1
            end
            scr:FillSelect(checkNumber(self._curQuestId) == checkNumber(self._allQuests[position]))
        end
        return cell
    end
end

function UIOverseaTowerInsideDialog:OnSelectQuest(id)
    local ind = self:GetInd()
    local go = self.ScrollView:GetShownItemByItemIndex(ind - 1)
    if go then
        local scr = CfUtils.GetLuaScr(go, TowerQuestCellPath)
        if scr then
            scr:FillSelect(false)
        end
    end
    self._curQuestId = id
    ind = self:GetInd()
    go = self.ScrollView:GetShownItemByItemIndex(ind - 1)
    if go then
        local scr = CfUtils.GetLuaScr(go, TowerQuestCellPath)
        if scr then
            scr:FillSelect(true)
        end
    end

    self:FillMainQuestInfo()
end

function UIOverseaTowerInsideDialog:OnFocus(focus)
    focus = checkBool(focus)
    if focus then
        CfUtils.SetTopCommonActive(true, true)
        GameUtils.UpdateNavBarShowGoods({ self.goodsId }, true)
        self:HideTopAddBtn()
    else
        GameUtils.RestoreHealthNodes()
    end
end

function UIOverseaTowerInsideDialog:FillMainQuestInfo()
    ---@type TowerQuestVo
    local vo = OverseaTowerUtils.GetTowerQuestVo(self._curQuestId)
    if not vo then
        return
    end
    local isUnlock = OverseaTowerUtils.IsUnlockQuest(self._curQuestId)
    local isPass = OverseaTowerUtils.IsPassQuest(self._curQuestId)

    CfUtils.SetActive(self.Lock, false)
    CfUtils.SetActive(self.Unlock, true)

    CfUtils.SetUISwitchText(self.TextNumber, self._curTowerType)
    CfUtils.SetUISwitchText(self.TextDecorate, self._curTowerType)
    CfUtils.SetUISwitchText(self.TextDesc, self._curTowerType)

    CfUtils.FillText(self.TextNumber, vo.storey)
    CfUtils.FillText(self.TextDesc, vo.name)

    CfUtils.FillText(self.TextNumber4, vo.proposalLevel)
    CfUtils.SetActive(self.ImgBoss, checkNumber(vo.monsteType) == 2)

    local isMain = (self._curTowerType == Constants.TowerType.Main)
    CfUtils.SetActive(self.CollectIncomeTips, isMain)
    CfUtils.SetActive(self.CommonGoodsListLight.transform.parent, true)
    -- fill 效果描述字段
    CfUtils.SetActive(self.Unlock:Find("Layout/MechanismsExplain"), not string.isEmpty(vo.effect))
    if not string.isEmpty(vo.effect) then
        local tipsTrans = self.Unlock:Find("Layout/MechanismsExplain/Tips")
        CfUtils.SetActive(tipsTrans, true)
        local tipsDesc = self.Unlock:Find("Layout/MechanismsExplain/Tips/Layout/TextDesc")
        if not isNull(tipsDesc) then
            CfUtils.FillText(tipsDesc, vo.effect)
        end
        local BtnExplain = self.Unlock:Find("Layout/MechanismsExplain/BtnExplain")
        if BtnExplain then
            SetButtonAction(BtnExplain, function()
                if CfUtils.IsActive(tipsTrans) then
                    CfUtils.SetActive(tipsTrans, false)
                else
                    CfUtils.SetActive(tipsTrans, true)
                end
            end)
        end
    end
    if isMain then
        local rewardVo = RewardConfMgr:GetInstance():GetQuestRewardVo(self._curQuestId)
        if rewardVo then
            local t = OverseaTowerUtils.GetQuestTotalReward(self._curQuestId)   -- 到当前层的全部奖励

            KTool.DestroyGameObjectChildren(self.Layout.gameObject, false)
            ---@type TowerQuestVo
            local questVo = OverseaTowerUtils.GetTowerQuestVo(self._curQuestId)
            for i, v in ipairs(t) do
                local go = CfUtils.InstantiateGo(self.Income, self.Layout)
                go.name = "go" .. i
                CfUtils.SetActive(go, true)
                local textNum = tostring(v.num) .. '/' .. tostring(v.time)
                CfUtils.FillText(go.transform:Find("TextNumber6"), textNum)
                local TF_Desc = go.transform:Find("TextDesc6")
                CfUtils.SetActive(TF_Desc, true)
                CfUtils.FillText(TF_Desc, localize("分钟"))
                local parVo = OverseaTowerUtils.GetClimbTowerConfigVo(i + 6)
                if parVo then
                    local tt = string.split(parVo.num, ";")
                    local rewardGroupId = checkNumber(questVo.rewardGroupId) % 100
                    local goodsId = tt[rewardGroupId]
                    if isNull(goodsId) then
                        goodsId = tt[1]
                    end
                    local goodBtn = go.transform:Find("BtnIcon/ImgGoodsIcon6")
                    if goodBtn then
                        CfUtils.FillImage(goodBtn, GoodsConfMgr:GetInstance():GetPhotoPathById(goodsId))
                        SetButtonAction(go.transform:Find("BtnIcon"), function()
                            local goodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                            local idType = GoodsUtils.GetIdType(goodsId)
                            if idType == Constants.IDType.GoodsUsable then
                                local rewards = OverseaTowerUtils.GetTowerRewardPoolVo(questVo.rewardGroupId)
                                if #rewards > 0 then
                                    GameUtils.ShowCommonTipsBoardRewardPreview(go, rewards)
                                end
                            else
                                GameUtils.ShowCommonTipsBoard(go, goodVo.name, goodVo.desc, goodVo.quality, goodVo.id)
                            end
                        end)
                    end
                end
            end
        end
    end

    local t = QuestConfMgr:GetInstance():GetEnemysDataInfo(vo.id)
    local isBoss = (checkNumber(vo.monsteType) == 2)
    SetButtonAction(self.Layout1.transform.parent:Find("Title"), function()
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIBossDetailDialog, parameters = { levelId = self._curQuestId } })
    end)
    KTool.DestroyGameObjectChildren(self.Layout1.gameObject, false)
    for k, v in pairs(t) do
        local go = CfUtils.InstantiateGo(self.MonsterNode.gameObject, self.Layout1)
        go.name = "go" .. k
        CfUtils.SetActive(go, true)
        local monstVo = CardConfMgr:GetInstance():GetBaseMonstVo(v.id)
        CfUtils.SetActive(go.transform:Find("ImgBoss"), false)
        if monstVo then
            local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(monstVo.skinId)
            if skinVo then
                CfUtils.FillImage(go.transform:Find("Mask1/ImgMonsterShadow"), skinVo.buffHead)
                CfUtils.FillImage(go.transform:Find("Mask2/ImgMonster"), skinVo.buffHead)
            end
            if isBoss then
                if checkNumber(monstVo.monsterClass) == Constants.RoleClass.Elite then
                    CfUtils.SetActive(go.transform:Find("ImgBoss"), true)
                end
            end
        end
    end

    local t = RewardConfMgr:GetInstance():GetTeamShowRewardData(self._curQuestId)
    local scr = CfUtils.GetLuaScr(self.CommonGoodsListLight, 'Game.Behaviours.CommonGoodsListLight')
    if scr then
        scr:FreshBaseUI(t, nil, isPass)
    end

    CfUtils.SetActive(self.TextDesc4, not isPass)
    CfUtils.SetActive(self.TextNumber4, not isPass)
    local underWayTrans = self.Layout1.transform.parent
    local finishTrans = self.Layout1.transform.parent.parent:Find("Finish")
    CfUtils.SetActive(finishTrans, isPass)
    if isPass then
        CfUtils.SetCanvasGroupAlpha(underWayTrans, 0.6)
        CfUtils.FillText(self.TextNumber4, localize("已经击败"))
    else
        CfUtils.SetCanvasGroupAlpha(underWayTrans, 1)
    end

    CfUtils.SetActive(self.CommonBtnConsumePop, not isMain and checkNumber(vo.unlockItem) > 0 and not isUnlock)
    if not isMain and checkNumber(vo.unlockItem) > 0 then
        CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, vo.unlockItem, vo.unlockItemNum)
    end
    CfUtils.SetUISwitchImage(self.ImgBg2, self._curTowerType)
    local TextDescText = self.TextDecorate.transform.parent:Find("TextDesc")
    ---@type TowerTypeVo
    local towerTypeVo = OverseaTowerUtils.GetTowerTypeVo(self._curTowerType)
    CfUtils.FillText(TextDescText, towerTypeVo.name)
    local titleBg = self.TextDecorate.transform.parent:Find("BgMask/ImgBg")
    local titleAttribute = self.TextDecorate.transform.parent:Find("ImgAttribute")
    CfUtils.SetUISwitchImage(self.ImgBg2, self._curTowerType)
    --CfUtils.SetUISwitchImage(titleBg, self._curTowerType)
    CfUtils.SetUISwitchImage(titleAttribute, self._curTowerType)
    local BgFxTrans = self.LeftPanel.transform.parent:Find("UIFX_TowerInside_BG")
    CfUtils.SetActive(BgFxTrans, checkNumber(self._curTowerType) == Constants.TowerType.Main)
    if checkNumber(self._curTowerType) == Constants.TowerType.Main then
        local floorLevel = checkNumber(vo.storey)
        local bgName = 'Arts/Textures/UIBg/action_tower_inner_bg_kl_2.png'
        local status = 300
        if floorLevel > 300 and floorLevel <= 600 then
            status = 600
            bgName = 'Arts/Textures/UIBg/action_tower_inner_bg_kl_3.png'
        elseif floorLevel > 600 and floorLevel <= 900 then
            status = 900
            bgName = 'Arts/Textures/UIBg/action_tower_inner_bg_kl_4.png'
        elseif floorLevel > 900 then
            status = 900
            bgName = 'Arts/Textures/UIBg/action_tower_inner_bg_kl_5.png'
        end
        CfUtils.SetActive(BgFxTrans, floorLevel > 300)
        if floorLevel > 300 then
            CfUtils.PlayAnimation(BgFxTrans, 'OverseaTowerInsideDialog_UIFX_TowerInside_' .. status)
        end
        CfUtils.FillImage(self.ImgBg, bgName)
    end
    if checkNumber(self._curTowerType) == Constants.TowerType.Main then
        local floorLevel = checkNumber(vo.storey)
        local status = 1
        if floorLevel <= 300 then
            status = 1
        elseif floorLevel > 300 and floorLevel <= 600 then
            status = 5
        elseif floorLevel > 600 and floorLevel <= 900 then
            status = 6
        else
            status = 7
        end
        CfUtils.SetUISwitchImage(titleBg, status)
        CfUtils.SetUISwitchText(self.TextNumber, status)
    else
        CfUtils.SetUISwitchImage(titleBg, self._curTowerType)
    end
    local isFightForce = not isPass
    CfUtils.SetActive(self.ArmForce, isFightForce)
    if isFightForce then
        CfUtils.FillText(self.ArmForce:Find("TextNumber4"), checkNumber(vo.proposalLevel))
    end
    if isUnlock then
        if isPass then
            self.FontStyleButton:ResetFontStyle("B17", localize("已经完成"))
        else
            self.FontStyleButton:ResetFontStyle("B5", localize("进入"))
        end
    else
        if checkNumber(vo.type) == Constants.TowerType.Main then
            self.FontStyleButton:ResetFontStyle("B17", localize("通关上一层解锁"))
            CfUtils.FillText(self.TextDesc2, localize("通关上一层解锁"))
        else
            self.FontStyleButton:ResetFontStyle("B17", localize("锁定中，使用钥匙解锁该层"))
            CfUtils.SetActive(self.Lock, not isUnlock)
            CfUtils.SetActive(self.Unlock, isUnlock)
            CfUtils.SetActive(self.Lock:Find("ImgMask"), false)
            CfUtils.FillText(self.TextDesc2, localize('锁定中，使用心灵特训通行证解锁'))
            CfUtils.SetActive(self.Tips, not isUnlock)
            if not isUnlock then
                ---未解锁的情况下
                ---@type GoodsVo
                local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(checkNumber(vo.unlockItem))
                CfUtils.FillImage(self.ImgGoodsIcon, goodsVo.photoPath)
                CfUtils.FillText(self.TextNumber1, checkNumber(vo.unlockItemNum))
            end
        end
    end
end

function UIOverseaTowerInsideDialog:OnBtnEnter()
    local isUnlock = OverseaTowerUtils.IsUnlockQuest(self._curQuestId)
    local isPass = OverseaTowerUtils.IsPassQuest(self._curQuestId)

    if not isUnlock then
        GameUtils.Toast(localize("通关上一层解锁"))
        return
    elseif isPass then
        GameUtils.Toast(localize("已经通关层数，无法重复挑战"))
        return
    end

    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = self._curQuestId } }, {
        { id = Constants.UITypeIds.UIOverseaTowerInsideDialog },
    })
end

function UIOverseaTowerInsideDialog:GetInd()
    local index = 0
    for k, v in pairs(self._allQuests) do
        if checkNumber(v) == checkNumber(self._curQuestId) then
            index = k
            break
        end
    end
    return index
end

function UIOverseaTowerInsideDialog:OnShow()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:FillSelf()
        local btnGlow = self.BtnUnlock.transform:Find("AnimRoot/UIFX_BtnUnlock/glow")
        local unlockBtnPoint = self.BtnUnlock.transform:Find("AnimRoot/UIFX_BtnUnlock/point")
        CfUtils.SetUISwitchParticleSystem(btnGlow, self._curTowerType)
        CfUtils.SetUISwitchParticleSystem(unlockBtnPoint, self._curTowerType)
        local ind = self:GetInd()
        self.ScrollView:MovePanelToItemIndex(ind - 4)
    end))
    return coWait
end

function UIOverseaTowerInsideDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end

        self._curTowerType = checkNumber(argument.type)
        if self._curTowerType <= 0 then
            return
        end
        if self._curTowerType == Constants.TowerType.Main then
            self.goodsId = Constants.Currency.HpId
        else
            self.goodsId = Constants.Currency.TowerTicket
        end
        if checkNumber(self._curTowerType) ~= Constants.TowerType.Main then
            ---@type TowerTypeVo
            local towerTypeVo = OverseaTowerUtils.GetTowerTypeVo(self._curTowerType)
            CfUtils.FillImage(self.ImgBg, towerTypeVo.modelId)
        end

        self:InitData()
    end))
    return coWait
end

function UIOverseaTowerInsideDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIOverseaTowerInsideDialog
